import{_ as i,a}from"./chunks/ecosystem.BHQSxcYD.js";import{_ as t,o as r,c as o,a3 as n}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"source_hash":"133cbb42c8","source_commit":"2bdf116"},"headers":[],"relativePath":"it/index.md","filePath":"it/index.md"}'),s={name:"it/index.md"};function l(d,e,c,p,h,u){return r(),o("div",null,[...e[0]||(e[0]=[n('<img src="'+i+'" style="zoom:70%;"><br><h2 id="what-is-xdrip" tabindex="-1">Cos&#39;è xDrip? <a class="header-anchor" href="#what-is-xdrip" aria-label="Permalink to &quot;Cos&#39;è xDrip? {#what-is-xdrip}&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>xDrip è un&#39;app Android non ufficiale e indipendente che fa da centro di raccolta ed elaborazione dei dati tra molti dispositivi diversi.</p><p>Supporta connessioni wireless con G6, One, One+, G7, Stelo, CareSens Air, Libre via NFC e Bluetooth, Aidex, Guardian, Simplera, microinfusori Medtronic, CGM Eversense, Libre 2 e 3, oltre a molte app di produttori di CGM o microinfusori (Pasta, iCan, CamAPS, Equil G, Vitatok, Glucotech, SiSensing e altre) tramite il lettore di notifiche dell&#39;app compagno. Supporta anche glucometri Bluetooth come Contour Next One, AccuChek Guide, Verio Flex e Diamond Mini, e dispositivi come la penna insulinica Pendiq 2.0.</p><p>I dati di frequenza cardiaca e contapassi vengono elaborati da smartwatch Android Wear, Garmin, Fitbit e Pebble, e dai quadranti che mostrano valori e grafici della glicemia.</p><p>L&#39;app offre grafici avanzati, molte opzioni di personalizzazione e inserimento dati, e un modello di simulazione predittiva.</p><p>Puoi sincronizzare istantaneamente i dati in entrambe le direzioni collegando telefoni follower; i dati possono anche essere caricati su e scaricati da un servizio web Nightscout, o caricati direttamente su Nocturne, Tidepool, MongoDB o InfluxDB.</p><p>Puoi personalizzare allarmi, letture vocali, preferenze di visualizzazione e altro. Gli utenti di tutto il mondo possono anche aggiornare le traduzioni direttamente dall&#39;app.</p><p>I tuoi dati sono tuoi e puoi esportarli in molti modi diversi. xDrip comunica anche con altre app, ad esempio inviando e ricevendo dati in tempo reale con <a href="https://androidaps.readthedocs.io/it/latest/index.html" target="_blank" rel="noreferrer">AndroidAPS</a>.</p><br><h2 id="ready-to-start-continue-here" tabindex="-1"><a href="./install/usethedoc.html">Pronto a iniziare? Continua qui!</a> <a class="header-anchor" href="#ready-to-start-continue-here" aria-label="Permalink to &quot;[Pronto a iniziare? Continua qui!](./install/usethedoc) {#ready-to-start-continue-here}&quot;">​</a></h2><br><h2 id="history" tabindex="-1">Storia <a class="header-anchor" href="#history" aria-label="Permalink to &quot;Storia {#history}&quot;">​</a></h2><p><a href="https://github.com/StephenBlackWasAlreadyTaken/DexDrip" target="_blank" rel="noreferrer">DexDrip</a> è stato creato da Emma Black nel 2014 ed è poi diventato <a href="http://stephenblackwasalreadytaken.github.io/xDrip/" target="_blank" rel="noreferrer">xDrip</a>, un&#39;app che raccoglieva i dati CGM da un ricevitore G4 o da un bridge e li inviava a <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a>. Era accompagnata dall&#39;app follower <a href="http://stephenblackwasalreadytaken.github.io/NightWatch/" target="_blank" rel="noreferrer">Nightwatch</a> (obsoleta).</p><p>Il progetto è stato poi modificato da @jamorham ed è diventato <a href="https://jamorham.github.io/#xdrip-plus" target="_blank" rel="noreferrer">xDrip</a>.</p><blockquote><p><em>Personal research version of xDrip</em></p></blockquote><img src="https://avatars.githubusercontent.com/u/12565568" style="zoom:33%;"><br><h2 id="disclaimer-and-warning" tabindex="-1"><strong>Avvertenze</strong> <a class="header-anchor" href="#disclaimer-and-warning" aria-label="Permalink to &quot;**Avvertenze** {#disclaimer-and-warning}&quot;">​</a></h2><ul><li><strong>Usi xDrip a tuo rischio: non usare le informazioni o il codice per prendere decisioni mediche.</strong></li><li>Il <a href="https://github.com/NightscoutFoundation/xDrip" target="_blank" rel="noreferrer">codice su github.com</a> è fornito senza garanzia né supporto formale di alcun tipo. Consulta la <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/LICENSE" target="_blank" rel="noreferrer">LICENZA</a> del repository per i dettagli.</li><li>Tutti i nomi di prodotti e aziende, marchi commerciali, marchi di servizio e marchi registrati appartengono ai rispettivi proprietari.</li></ul><p><strong>Nota:</strong> questo progetto non è associato né approvato da: Abbott Laboratories, Aidex, Ascenia, i-Sens, Companion Medical, Dexcom, Medtronic, Lifescan, Medtrum, Pendiq, Roche, Senseonics, Sibionics, GlucoRx.</p>',23)])])}const f=t(s,[["render",l]]);export{b as __pageData,f as default};
